@Component({
    selector: 'chat-debug',
    standalone: true,
    imports: [TimelineInspectorComponent, StateInspectorComponent],
    changeDetection: ChangeDetectionStrategy.OnPush,
    styles: [
        CHAT_DEBUG_TOKENS,
        `
      :host {
        display: contents;
      }

      /* ── Status pill launcher ─────────────────────────────────────── */
      .launcher {
        position: fixed;
        top: 20px;
        right: 20px;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 36px;
        height: 36px;
        border-radius: var(--tplane-chat-debug-radius-pill);
        background: var(--tplane-chat-debug-bg);
        border: 1px solid var(--tplane-chat-debug-border);
        color: var(--tplane-chat-debug-text);
        cursor: pointer;
        z-index: 990;
        box-shadow: var(--tplane-chat-debug-shadow-pill);
        transition: background 120ms ease, border-color 120ms ease;
        padding: 0;
      }
      .launcher:hover {
        background: var(--tplane-chat-debug-surface);
        border-color: var(--tplane-chat-debug-border-strong);
      }
      .launcher__dot {
        width: 8px;
        height: 8px;
        border-radius: 50%;
        background: var(--tplane-chat-debug-success);
        box-shadow: 0 0 8px
          color-mix(in srgb, var(--tplane-chat-debug-success) 60%, transparent);
      }
      .launcher__dot--streaming {
        background: var(--tplane-chat-debug-accent);
        box-shadow: 0 0 8px
          color-mix(in srgb, var(--tplane-chat-debug-accent) 70%, transparent);
        animation: chat-debug-pill-pulse 1.2s ease-in-out infinite;
      }
      @keyframes chat-debug-pill-pulse {
        0%,
        100% {
          opacity: 1;
          transform: scale(1);
        }
        50% {
          opacity: 0.6;
          transform: scale(0.85);
        }
      }

      /* ── Docked panel ─────────────────────────────────────────────── */
      .panel {
        position: fixed;
        background: var(--tplane-chat-debug-bg);
        color: var(--tplane-chat-debug-text);
        border: 1px solid var(--tplane-chat-debug-border);
        z-index: 991;
        display: flex;
        flex-direction: column;
        box-shadow: var(--tplane-chat-debug-shadow-panel);
        animation: chat-debug-panel-enter 120ms ease;
      }
      .panel--right {
        top: 0;
        right: var(--tplane-chat-sidebar-claim-right, 0);
        bottom: 0;
        width: var(--panel-size, 420px);
        border-right: 0;
        border-top-left-radius: var(--tplane-chat-debug-radius-panel);
        border-bottom-left-radius: var(--tplane-chat-debug-radius-panel);
        transform-origin: bottom right;
        transition: right 200ms ease-out;
      }
      .panel--left {
        top: 0;
        left: 0;
        bottom: 0;
        width: var(--panel-size, 420px);
        border-left: 0;
        border-top-right-radius: var(--tplane-chat-debug-radius-panel);
        border-bottom-right-radius: var(--tplane-chat-debug-radius-panel);
        transform-origin: bottom left;
      }
      .panel--bottom {
        left: 0;
        right: var(--tplane-chat-sidebar-claim-right, 0);
        bottom: 0;
        height: var(--panel-size, 40vh);
        border-bottom: 0;
        border-top-left-radius: var(--tplane-chat-debug-radius-panel);
        border-top-right-radius: var(--tplane-chat-debug-radius-panel);
        transform-origin: bottom right;
        transition: right 200ms ease-out;
      }
      /* Mobile breakpoint: when an edge-claimer occupies the right and
       the device is narrow, the bottom strip's effective width is
       ~zero. Explicitly hide it so it doesn't intercept pointer events
       on the sidebar drawer. The chat-debug launcher remains visible. */
      @media (max-width: 767px) {
        .panel--bottom {
          display: none;
        }
      }
      @keyframes chat-debug-panel-enter {
        from {
          opacity: 0;
          transform: scale(0.96);
        }
        to {
          opacity: 1;
          transform: scale(1);
        }
      }

      .panel__header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 12px 16px;
        border-bottom: 1px solid var(--tplane-chat-debug-border);
        min-height: 44px;
        box-sizing: border-box;
      }
      .panel__title {
        margin: 0;
        font-size: 13px;
        font-weight: 600;
        letter-spacing: -0.01em;
        color: var(--tplane-chat-debug-text);
      }
      .panel__actions {
        display: flex;
        align-items: center;
        gap: 4px;
      }

      .panel__dock-group {
        display: inline-flex;
        gap: 0;
        padding: 2px;
        background: var(--tplane-chat-debug-bg-deep);
        border: 1px solid var(--tplane-chat-debug-border);
        border-radius: 6px;
      }
      .panel__dock-btn {
        appearance: none;
        background: transparent;
        border: 0;
        border-radius: 4px;
        width: 24px;
        height: 22px;
        padding: 0;
        color: var(--tplane-chat-debug-text-subtle);
        cursor: pointer;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        transition: background 120ms ease, color 120ms ease;
      }
      .panel__dock-btn:hover {
        color: var(--tplane-chat-debug-text);
      }
      .panel__dock-btn.is-active {
        background: var(--tplane-chat-debug-border);
        color: var(--tplane-chat-debug-text);
      }
      .panel__dock-btn svg {
        display: block;
      }

      .panel__close {
        appearance: none;
        background: transparent;
        border: 0;
        border-radius: 6px;
        width: 26px;
        height: 26px;
        margin-left: 4px;
        color: var(--tplane-chat-debug-text-subtle);
        cursor: pointer;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        transition: background 120ms ease, color 120ms ease;
      }
      .panel__close:hover {
        background: var(--tplane-chat-debug-surface);
        color: var(--tplane-chat-debug-text);
      }

      .panel__controls {
        border-bottom: 1px solid var(--tplane-chat-debug-border);
        overflow-y: auto;
        max-height: 50%;
        background: var(--tplane-chat-debug-bg);
      }
      .panel__controls:empty {
        display: none;
      }

      .panel__tabs {
        display: flex;
        gap: 4px;
        border-bottom: 1px solid var(--tplane-chat-debug-border);
        padding: 0 12px;
        background: var(--tplane-chat-debug-bg);
      }
      .panel__tab {
        appearance: none;
        background: transparent;
        border: 0;
        border-bottom: 2px solid transparent;
        padding: 10px 8px;
        font: inherit;
        font-size: 13px;
        font-weight: 500;
        color: var(--tplane-chat-debug-text-muted);
        cursor: pointer;
        transition: color 120ms ease, border-color 120ms ease;
        margin-bottom: -1px;
      }
      .panel__tab:hover {
        color: var(--tplane-chat-debug-text);
      }
      .panel__tab.is-active {
        color: var(--tplane-chat-debug-text);
        border-bottom-color: var(--tplane-chat-debug-accent);
      }

      .panel__body {
        flex: 1;
        min-height: 0;
        overflow: hidden;
        display: flex;
        flex-direction: column;
        background: var(--tplane-chat-debug-bg);
      }
    `,
    ],
    template: `
    @if (!open() && launcher() === 'floating') {
    <button
      type="button"
      class="launcher"
      title="Open chat devtools"
      aria-label="Open chat devtools"
      [attr.aria-pressed]="false"
      (click)="setOpen(true)"
    >
      <span
        class="launcher__dot"
        [class.launcher__dot--streaming]="isStreaming()"
        aria-hidden="true"
      ></span>
    </button>
    } @else if (open() && agent(); as currentAgent) {
    <div
      class="panel"
      [class.panel--right]="dockState() === 'right'"
      [class.panel--bottom]="dockState() === 'bottom'"
      [class.panel--left]="dockState() === 'left'"
      role="region"
      aria-label="Chat devtools"
    >
      <div class="panel__header">
        <h3 class="panel__title">Chat Devtools</h3>
        <div class="panel__actions">
          <div
            class="panel__dock-group"
            role="group"
            aria-label="Dock position"
          >
            <button
              type="button"
              class="panel__dock-btn"
              [class.is-active]="dockState() === 'left'"
              (click)="setDock('left')"
              aria-label="Dock left"
            >
              <svg
                width="14"
                height="14"
                viewBox="0 0 14 14"
                fill="none"
                stroke="currentColor"
                stroke-width="1.5"
                stroke-linecap="round"
                stroke-linejoin="round"
              >
                <rect x="1.5" y="2.5" width="11" height="9" rx="1.2" />
                <line x1="5.5" y1="2.5" x2="5.5" y2="11.5" />
              </svg>
            </button>
            <button
              type="button"
              class="panel__dock-btn"
              [class.is-active]="dockState() === 'bottom'"
              (click)="setDock('bottom')"
              aria-label="Dock bottom"
            >
              <svg
                width="14"
                height="14"
                viewBox="0 0 14 14"
                fill="none"
                stroke="currentColor"
                stroke-width="1.5"
                stroke-linecap="round"
                stroke-linejoin="round"
              >
                <rect x="1.5" y="2.5" width="11" height="9" rx="1.2" />
                <line x1="1.5" y1="8.5" x2="12.5" y2="8.5" />
              </svg>
            </button>
            <button
              type="button"
              class="panel__dock-btn"
              [class.is-active]="dockState() === 'right'"
              (click)="setDock('right')"
              aria-label="Dock right"
            >
              <svg
                width="14"
                height="14"
                viewBox="0 0 14 14"
                fill="none"
                stroke="currentColor"
                stroke-width="1.5"
                stroke-linecap="round"
                stroke-linejoin="round"
              >
                <rect x="1.5" y="2.5" width="11" height="9" rx="1.2" />
                <line x1="8.5" y1="2.5" x2="8.5" y2="11.5" />
              </svg>
            </button>
          </div>
          <button
            type="button"
            class="panel__close"
            (click)="setOpen(false)"
            aria-label="Close"
          >
            <svg
              width="14"
              height="14"
              viewBox="0 0 14 14"
              fill="none"
              stroke="currentColor"
              stroke-width="1.75"
              stroke-linecap="round"
              stroke-linejoin="round"
            >
              <line x1="3" y1="3" x2="11" y2="11" />
              <line x1="11" y1="3" x2="3" y2="11" />
            </svg>
          </button>
        </div>
      </div>

      @if (tabs().length > 1) {
      <div class="panel__tabs" role="tablist">
        @for (tab of tabs(); track tab.id) {
        <button
          type="button"
          role="tab"
          class="panel__tab"
          [class.is-active]="tab.id === activeTabId()"
          [attr.aria-selected]="tab.id === activeTabId()"
          (click)="setActiveTab(tab.id)"
        >
          {{ tab.label }}
        </button>
        }
      </div>
      }

      <div class="panel__body">
        @switch (activeTab()?.kind) { @case ('builtin-timeline') { @if
        (historyAgent(); as history) {
        <chat-debug-timeline-inspector
          [agent]="history"
          (replayRequested)="replayRequested.emit($event)"
          (forkRequested)="forkRequested.emit($event)"
        />
        } } @case ('builtin-state') {
        <chat-debug-state-tab [agent]="currentAgent" />
        } }
      </div>
    </div>
    }
  `,
})
export class ChatDebugComponent {
    readonly agent = input<DebugAgent | DebugAgentWithHistory | null>(null);
    readonly dock = input<DockPosition>('right');
    readonly defaultOpen = input<boolean>(false);
    readonly launcher = input<'floating' | 'none'>('floating');
    readonly storageKey = input<string>('chat-debug');
    readonly replayRequested = output<string>();
    readonly forkRequested = output<string>();
    readonly openChange = output<boolean>();
    readonly dockChange = output<DockPosition>();
    protected readonly open = signal<boolean>(false);
    protected readonly dockState = signal<DockPosition>('right');
    private readonly userDockOverride = signal<boolean>(false);
    protected readonly activeTabId = signal<string>('timeline');
    protected readonly historyAgent = computed(() => {
        const agent = this.agent();
        return agent && hasHistory(agent) ? agent : null;
    });
    private readonly hydrated = signal(false);
    protected readonly isStreaming = computed(() => {
        const status = this.agent()?.status?.();
        return status === 'running';
    });
    protected readonly tabs = computed((): TabEntry[] => {
        if (!this.agent())
            return [];
        return [
            ...(this.historyAgent()
                ? [
                    {
                        id: 'timeline',
                        label: 'Timeline',
                        kind: 'builtin-timeline',
                    } satisfies TabEntry,
                ]
                : []),
            { id: 'state', label: 'State', kind: 'builtin-state' },
        ];
    });
    protected readonly activeTab = computed(() => this.tabs().find((t) => t.id === this.activeTabId()));
    private readonly hostEl: ElementRef<HTMLElement> = inject(ElementRef);
    constructor() {
        ensureChatDebugRootStyles();
        effect(() => {
            const tabs = this.tabs();
            if (tabs.length === 0)
                return;
            if (tabs.some((tab) => tab.id === this.activeTabId()))
                return;
            this.activeTabId.set(tabs[0].id);
        });
        afterNextRender(() => {
            const restore = createPersistence(this.storageKey());
            const persistedOpen = restore.read<boolean>('open');
            if (!this.open()) {
                this.open.set(persistedOpen ?? this.defaultOpen());
            }
            const persistedDock = restore.read<DockPosition>('dock');
            this.dockState.set(persistedDock ?? this.dock());
            const persistedTab = restore.read<string>('tab');
            if (persistedTab)
                this.activeTabId.set(persistedTab);
            this.hydrated.set(true);
        });
        effect(() => {
            if (!this.hydrated())
                return;
            const p = createPersistence(this.storageKey());
            p.write('open', this.open());
            p.write('dock', this.dockState());
            p.write('tab', this.activeTabId());
        });
        effect(() => {
            if (typeof document === 'undefined')
                return;
            const html = document.documentElement;
            if (this.open()) {
                html.dataset['threadplaneChatDebug'] = this.dockState();
            }
            else {
                delete html.dataset['threadplaneChatDebug'];
            }
        });
        effect(() => {
            const isOpen = this.open();
            if (!isOpen)
                return;
            if (this.userDockOverride())
                return;
            if (typeof document === 'undefined')
                return;
            if (!document.querySelector('chat-sidebar'))
                return;
            this.dockState.set('bottom');
        });
    }
    setOpen(value: boolean): void {
        this.open.set(value);
        this.openChange.emit(value);
    }
    setDock(next: DockPosition): void {
        this.userDockOverride.set(true);
        this.dockState.set(next);
        this.dockChange.emit(next);
    }
    setActiveTab(id: string): void {
        this.activeTabId.set(id);
    }
    @HostListener('document:keydown.escape')
    protected onEsc(): void {
        if (this.open())
            this.setOpen(false);
    }
    @HostListener('document:click', ['$event'])
    protected onDocumentClick(event: MouseEvent): void {
        if (!this.open())
            return;
        const path = event.composedPath();
        if (path.includes(this.hostEl.nativeElement))
            return;
        this.setOpen(false);
    }
}

@Component({
    selector: 'chat-debug-checkpoint-card',
    standalone: true,
    changeDetection: ChangeDetectionStrategy.OnPush,
    styles: [
        CHAT_DEBUG_TOKENS,
        `
    .debug-checkpoint-card {
      width: 100%;
      text-align: left;
      border-radius: var(--tplane-chat-radius-card);
      border: 1px solid var(--tplane-chat-separator);
      padding: 8px 12px;
      cursor: pointer;
      background: var(--tplane-chat-bg);
      transition: background 150ms ease, border-color 150ms ease;
    }
    .debug-checkpoint-card:hover {
      background: color-mix(in srgb, var(--tplane-chat-text) 5%, transparent);
    }
    .debug-checkpoint-card--selected {
      border-color: var(--tplane-chat-text-muted);
      background: color-mix(in srgb, var(--tplane-chat-text) 5%, transparent);
    }
    .debug-checkpoint-card__title {
      font-size: var(--tplane-chat-font-size-xs);
      font-weight: 500;
      color: var(--tplane-chat-text);
      margin: 0;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .debug-checkpoint-card__meta {
      display: flex;
      gap: 8px;
      margin-top: 4px;
    }
    .debug-checkpoint-card__badge {
      font-size: var(--tplane-chat-font-size-xs);
      padding: 2px 6px;
      border-radius: 4px;
      background: var(--tplane-chat-surface-alt);
      color: var(--tplane-chat-text-muted);
    }
    `,
    ],
    template: `
    <button
      class="debug-checkpoint-card"
      [class.debug-checkpoint-card--selected]="isSelected()"
      (click)="selected.emit()"
    >
      <p class="debug-checkpoint-card__title">{{ checkpoint().node ?? 'Unknown' }}</p>
      <div class="debug-checkpoint-card__meta">
        @if (checkpoint().duration !== null && checkpoint().duration !== undefined) {
          <span class="debug-checkpoint-card__badge">{{ checkpoint().duration }}ms</span>
        }
        @if (checkpoint().tokenCount !== null && checkpoint().tokenCount !== undefined) {
          <span class="debug-checkpoint-card__badge">{{ checkpoint().tokenCount }} tok</span>
        }
      </div>
    </button>
  `,
})
export class DebugCheckpointCardComponent {
    readonly checkpoint = input.required<DebugCheckpoint>();
    readonly isSelected = input<boolean>(false);
    readonly selected = output<void>();
}

@Component({
    selector: 'chat-debug-state-diff',
    standalone: true,
    imports: [JsonPipe],
    changeDetection: ChangeDetectionStrategy.OnPush,
    styles: [
        CHAT_DEBUG_TOKENS,
        `
    .debug-state-diff__empty {
      font-size: var(--tplane-chat-font-size-xs);
      color: var(--tplane-chat-text-muted);
      font-style: italic;
      margin: 0;
    }
    .debug-state-diff__list {
      display: flex;
      flex-direction: column;
      gap: 4px;
    }
    .debug-state-diff__entry {
      font-size: var(--tplane-chat-font-size-xs);
      font-family: var(--tplane-chat-font-mono);
      padding: 4px 8px;
      border-radius: 4px;
    }
    .debug-state-diff__entry--added {
      background: var(--tplane-chat-surface-alt);
      color: var(--tplane-chat-success);
    }
    .debug-state-diff__entry--removed {
      background: var(--tplane-chat-error-bg);
      color: var(--tplane-chat-error-text);
    }
    .debug-state-diff__entry--changed {
      background: var(--tplane-chat-warning-bg);
      color: var(--tplane-chat-warning-text);
    }
    .debug-state-diff__key { font-weight: 600; }
    .debug-state-diff__value {
      display: block;
      padding-left: 16px;
      color: var(--tplane-chat-text-muted);
    }
    `,
    ],
    template: `
    @if (diffEntries().length === 0) {
      <p class="debug-state-diff__empty">No changes</p>
    } @else {
      <div class="debug-state-diff__list">
        @for (entry of diffEntries(); track entry.path) {
          <div class="debug-state-diff__entry" [class]="entryClass(entry.type)">
            <span class="debug-state-diff__key">{{ prefix(entry.type) }} {{ entry.path }}</span>
            @if (entry.type === 'changed') {
              <span class="debug-state-diff__value">{{ entry.before | json }} &rarr; {{ entry.after | json }}</span>
            } @else if (entry.type === 'added') {
              <span class="debug-state-diff__value">{{ entry.after | json }}</span>
            } @else {
              <span class="debug-state-diff__value">{{ entry.before | json }}</span>
            }
          </div>
        }
      </div>
    }
  `,
})
export class DebugStateDiffComponent {
    readonly before = input<Record<string, unknown>>({});
    readonly after = input<Record<string, unknown>>({});
    readonly diffEntries = computed((): DiffEntry[] => computeStateDiff(this.before(), this.after()));
    prefix(type: DiffEntry['type']): string {
        switch (type) {
            case 'added': return '+';
            case 'removed': return '-';
            case 'changed': return '~';
        }
    }
    entryClass(type: DiffEntry['type']): string {
        switch (type) {
            case 'added': return 'debug-state-diff__entry--added';
            case 'removed': return 'debug-state-diff__entry--removed';
            case 'changed': return 'debug-state-diff__entry--changed';
        }
    }
    colorClass(type: DiffEntry['type']): string {
        return this.entryClass(type);
    }
}

@Component({
    selector: 'chat-debug-state-inspector',
    standalone: true,
    imports: [JsonPipe],
    changeDetection: ChangeDetectionStrategy.OnPush,
    styles: [
        CHAT_DEBUG_TOKENS,
        `
    .debug-state-inspector {
      overflow: auto;
      max-height: 256px;
    }
    .debug-state-inspector__pre {
      font-size: var(--tplane-chat-font-size-xs);
      font-family: var(--tplane-chat-font-mono);
      color: var(--tplane-chat-text);
      white-space: pre-wrap;
      word-break: break-all;
      margin: 0;
    }
    `,
    ],
    template: `
    <div class="debug-state-inspector">
      <pre class="debug-state-inspector__pre">{{ state() | json }}</pre>
    </div>
  `,
})
export class DebugStateInspectorComponent {
    readonly state = input<Record<string, unknown>>({});
}

@Component({
    selector: 'chat-debug-state-tab',
    standalone: true,
    imports: [DebugStateInspectorComponent],
    changeDetection: ChangeDetectionStrategy.OnPush,
    styles: [
        CHAT_DEBUG_TOKENS,
        `
    :host { display: flex; flex-direction: column; height: 100%; background: var(--tplane-chat-debug-bg); }
    .state__header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 10px 16px;
      border-bottom: 1px solid var(--tplane-chat-debug-border);
      background: var(--tplane-chat-debug-bg);
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      color: var(--tplane-chat-debug-text-subtle);
    }
    .state__copy {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: var(--tplane-chat-debug-bg-deep);
      border: 1px solid var(--tplane-chat-debug-border);
      border-radius: 6px;
      padding: 3px 8px;
      font: inherit;
      font-size: 11px;
      letter-spacing: 0;
      text-transform: none;
      color: var(--tplane-chat-debug-text-muted);
      cursor: pointer;
      transition: color 120ms ease, border-color 120ms ease;
    }
    .state__copy:hover {
      color: var(--tplane-chat-debug-text);
      border-color: var(--tplane-chat-debug-border-strong);
    }
    .state__copy.is-copied {
      color: var(--tplane-chat-debug-success);
      border-color: var(--tplane-chat-debug-success);
    }
    .state__copy svg { display: block; }
    .state__body {
      flex: 1;
      overflow-y: auto;
      padding: 12px 16px;
      color: var(--tplane-chat-debug-text);
    }
    `,
