@Component({
    selector: 'a2ui-surface',
    standalone: true,
    imports: [
        RenderSpecComponent,
        A2uiDefaultFallbackComponent,
        NgComponentOutlet,
    ],
    changeDetection: ChangeDetectionStrategy.OnPush,
    host: {
        '[style.--a2ui-primary]': 'primaryColor()',
    },
    styles: `
    .a2ui-surface-chrome {
