            [attr.aria-controls]="listId"
            [attr.aria-activedescendant]="activeRowId()"
            [placeholder]="placeholder()"
            [value]="query()"
            (input)="onInput($event)"
            (keydown)="onInputKeydown($event)"
          />
          <button
            type="button"
