export function createA2uiMessageParser(): A2uiMessageParser {
    let buffer = '';
    function parseEnvelope(json: Record<string, unknown>): A2uiMessage | null {
        for (const key of ENVELOPE_KEYS) {
            if (key in json && typeof json[key] === 'object' && json[key] !== null) {
                const version = typeof json['version'] === 'string' ? json['version'] : A2UI_WIRE_VERSION;
                return { version, [key]: json[key] } as unknown as A2uiMessage;
            }
        }
        return null;
    }
    function push(chunk: string): A2uiMessage[] {
        buffer += chunk;
        const messages: A2uiMessage[] = [];
        let newlineIndex: number;
        while ((newlineIndex = buffer.indexOf('\n')) !== -1) {
            const line = buffer.slice(0, newlineIndex).trim();
            buffer = buffer.slice(newlineIndex + 1);
            if (!line)
                continue;
            try {
                const json = JSON.parse(line);
                if (json && typeof json === 'object' && !Array.isArray(json)) {
                    const msg = parseEnvelope(json as Record<string, unknown>);
                    if (msg)
                        messages.push(msg);
                }
            }
            catch {
            }
        }
        return messages;
    }
    return { push };
}

export function deleteByPointer(model: Record<string, unknown>, pointer: string): Record<string, unknown> {
    const segments = parsePointer(pointer);
    if (segments.length === 0)
        return {};
    const parentPath = segments.slice(0, -1);
    const key = segments[segments.length - 1];
    if (parentPath.length === 0) {
        const copy = { ...model };
        delete copy[key];
        return copy;
    }
    const parent = getByPointer(model, '/' + parentPath.join('/'));
    if (parent == null || typeof parent !== 'object')
        return model;
    if (Array.isArray(parent)) {
        const parentCopy = [...(parent as unknown[])];
        parentCopy[Number(key)] = undefined;
        return setByPointer(model, '/' + parentPath.join('/'), parentCopy);
    }
    const parentCopy = { ...(parent as Record<string, unknown>) };
    delete parentCopy[key];
    return setByPointer(model, '/' + parentPath.join('/'), parentCopy);
}

export function getByPointer(model: Record<string, unknown>, pointer: string): unknown {
    const segments = parsePointer(pointer);
    let current: unknown = model;
    for (const seg of segments) {
        if (current == null || typeof current !== 'object')
            return undefined;
        current = (current as Record<string, unknown>)[seg];
    }
    return current;
}

export function isFunctionCall(value: unknown): value is {
    call: string;
    args?: Record<string, unknown>;
} {
    return typeof value === 'object' && value !== null
        && 'call' in value && typeof (value as {
        call: unknown;
    }).call === 'string';
}

export function isPathRef(value: unknown): value is {
    path: string;
} {
    return typeof value === 'object' && value !== null
        && 'path' in value && typeof (value as {
        path: unknown;
    }).path === 'string';
}

export function resolveDynamic(value: unknown, model: Record<string, unknown>, scope?: A2uiScope, registry?: A2uiFunctionRegistry): unknown {
    if (value == null)
        return value;
    if (Array.isArray(value))
        return value.map(item => resolveDynamic(item, model, scope, registry));
    if (isFunctionCall(value)) {
        if (!registry)
            return undefined;
        const impl = registry.get(value.call);
        if (!impl) {
            warnUnknownA2uiFunction(value.call);
            return undefined;
        }
        const args = (value.args ?? {}) as Record<string, unknown>;
        return withActiveRegistry(registry, () => impl(args, {
            resolveArg: (v) => resolveDynamic(v, model, scope, registry),
        }));
    }
    if (isPathRef(value))
        return resolvePathRef(value, model, scope);
    return value;
}

export function setByPointer(model: Record<string, unknown>, pointer: string, value: unknown): Record<string, unknown> {
    const segments = parsePointer(pointer);
    if (segments.length === 0)
        return value as Record<string, unknown>;
    function clone(obj: unknown, segs: string[], val: unknown): unknown {
        if (segs.length === 0)
            return val;
        const [head, ...rest] = segs;
        const base = (obj != null && typeof obj === 'object') ? obj : {};
        const isArray = Array.isArray(base);
        const copy = isArray ? [...(base as unknown[])] : { ...(base as Record<string, unknown>) };
        (copy as Record<string, unknown>)[head] = clone((base as Record<string, unknown>)[head], rest, val);
        return copy;
    }
    return clone(model, segments, value) as Record<string, unknown>;
}

