    submit: (input: AgentSubmitInput, opts?: AgentSubmitOptions) => Promise<void>;
    stop: () => Promise<void>;
    retry: () => Promise<void>;
    regenerate: (assistantMessageIndex: number) => Promise<void>;
    interrupt?: Signal<AgentInterrupt | undefined>;
    subagents?: Signal<Map<string, Subagent>>;
    clientTools?: ClientToolsCapability;
    checkStatus?: () => Promise<void>;
    events$: Observable<AgentEvent>;
}

export interface AgentCheckpoint {
    id?: string;
    label?: string;
    values: Record<string, unknown>;
}

export interface AgentCustomEvent {
    readonly type: 'custom';
    readonly name: string;
    readonly data: unknown;
}

export class AgentError extends Error {
    readonly kind: AgentErrorKind;
    readonly retryable: boolean;
    readonly status?: number;
    override readonly cause: unknown;
    readonly recovery?: AgentRecovery;
    readonly detail?: string;
    constructor(init: {
        kind: AgentErrorKind;
        message: string;
        retryable: boolean;
        status?: number;
        cause?: unknown;
        recovery?: AgentRecovery;
        detail?: string;
    }) {
        super(init.message);
        this.name = 'AgentError';
        this.kind = init.kind;
        this.retryable = init.retryable;
        this.status = init.status;
        this.cause = init.cause;
        this.recovery = init.recovery;
        this.detail = init.detail;
    }
}

