            });
        }
    }
    protected async performMoveUp(threadId: string): Promise<void> {
        const pinned = this.threads().filter((t) => t.pinned === true);
        const idx = pinned.findIndex((t) => t.id === threadId);
        if (idx <= 0)
            return;
        const beforeId = pinned[idx - 1].id;
