export function buildA2uiActionMessage(params: Record<string, unknown>, surface: A2uiSurface): A2uiActionMessage {
    const context = (params['context'] as Record<string, unknown>) ?? {};
    const sourceComponentId = params['sourceComponentId'] as string;
    const message: A2uiActionMessage = {
        version: A2UI_WIRE_VERSION,
        action: {
            name: params['name'] as string,
            surfaceId: surface.surfaceId,
            sourceComponentId,
            timestamp: new Date().toISOString(),
            context,
        },
    };
    const label = deriveActionLabel(surface, sourceComponentId);
    if (label)
        message.action.label = label;
    if (surface.sendDataModel) {
        message.metadata = {
            a2uiClientDataModel: {
                surfaces: { [surface.surfaceId]: surface.dataModel },
            },
        };
    }
    return message;
}

export function cancelledClientToolResult(toolCallId: string): ClientToolResult {
    return {
        ok: false,
        error: `client tool execution cancelled before completion: ${toolCallId}`,
    };
}

export function citationSourceVisual(c: Citation): CitationSourceVisual {
    const iconUrl = c.iconUrl?.trim();
    if (iconUrl) {
        return { kind: 'image', iconUrl };
    }
    const meta = citationTypeMeta(c);
    if (meta.icon !== 'web') {
        return {
            kind: 'type-icon',
            icon: meta.icon,
            tone: meta.tone,
            label: meta.label,
        };
    }
    return {
        kind: 'monogram',
        monogram: deriveMonogram(c),
        color: monogramColor(c),
    };
}

export function citationTypeLabel(c: Citation): string | null {
    return citationTypeMeta(c).label;
}

export function citationTypeMeta(c: Citation): CitationTypeMeta {
    const type = deriveSourceType(c);
    const canonicalType = type.toLowerCase();
    if (isKnownType(canonicalType)) {
        return {
            type: canonicalType,
            label: KNOWN_TYPE_LABELS[canonicalType],
            icon: canonicalType,
            tone: canonicalType,
            isKnown: true,
        };
    }
    return {
        type,
        label: type === 'unknown' ? null : readableSourceTypeLabel(type),
        icon: 'generic',
        tone: 'generic',
        isKnown: false,
    };
}

export function clientToolGuardFailureResult(toolCallId: string, error: unknown): ClientToolResult {
    const message = error instanceof Error ? error.message : String(error);
    return {
        ok: false,
        error: `client tool execution guard failed for ${toolCallId}: ${message}`,
    };
}

export function completeDelivery<const TOutcome extends CompleteOutcome>(generation: string, outcome: TOutcome) {
    const delivery = { generation, phase: 'complete', outcome } as const;
    return delivery satisfies MessageDelivery;
}

export function createA2uiSurfaceStore(): A2uiSurfaceStore {
    const surfacesSignal = signal<Map<string, A2uiSurface>>(new Map());
    const surfaceStatesSignal = signal<Map<string, A2uiSurfaceState>>(new Map());
    const buffers = new Map<string, SurfaceBuffer>();
    function bufferOf(surfaceId: string): SurfaceBuffer {
        let b = buffers.get(surfaceId);
        if (!b) {
            b = { components: new Map(), componentViews: new Map(), dataModelDeltas: [] };
            buffers.set(surfaceId, b);
        }
        return b;
    }
    function publish(surface: A2uiSurface, views: Map<string, A2uiComponentView>): void {
        const nextSurfaces = new Map(surfacesSignal());
        nextSurfaces.set(surface.surfaceId, surface);
        surfacesSignal.set(nextSurfaces);
        const nextStates = new Map(surfaceStatesSignal());
        nextStates.set(surface.surfaceId, { surface, componentViews: views });
        surfaceStatesSignal.set(nextStates);
    }
    function refreshViews(views: ReadonlyMap<string, A2uiComponentView>, dataModel: Record<string, unknown>): Map<string, A2uiComponentView> {
        const next = new Map<string, A2uiComponentView>();
        for (const [id, v] of views) {
            const allResolved = v.bindings.every((p) => isResolved(dataModel, p));
            const nextReady = v.ready || allResolved;
            next.set(id, {
                ...v,
                ready: nextReady,
                props: nextReady ? resolveViewProps(v.def, dataModel) : v.props,
            });
        }
        return next;
    }
    function tryCommit(surfaceId: string): void {
        const b = buffers.get(surfaceId);
        if (!b || !b.create || !b.components.has('root'))
            return;
        let dataModel: Record<string, unknown> = {};
        for (const d of b.dataModelDeltas) {
            dataModel = applyDataModelDelta(dataModel, d);
        }
        const surface: A2uiSurface = {
            surfaceId,
            catalogId: b.create.catalogId,
            ...(b.create.theme ? { theme: b.create.theme } : {}),
            ...(b.create.sendDataModel !== undefined ? { sendDataModel: b.create.sendDataModel } : {}),
            components: new Map(b.components),
            dataModel,
        };
        publish(surface, refreshViews(b.componentViews, dataModel));
        buffers.delete(surfaceId);
    }
    function apply(message: A2uiMessage): void {
        if ('createSurface' in message) {
            const create = message.createSurface;
            const live = surfacesSignal().get(create.surfaceId);
            if (live) {
                const state = surfaceStatesSignal().get(create.surfaceId);
                const surface: A2uiSurface = {
                    ...live,
                    catalogId: create.catalogId,
                    ...(create.theme !== undefined ? { theme: create.theme } : {}),
                    ...(create.sendDataModel !== undefined ? { sendDataModel: create.sendDataModel } : {}),
                };
                publish(surface, new Map(state?.componentViews ?? []));
                return;
            }
            bufferOf(create.surfaceId).create = create;
            tryCommit(create.surfaceId);
            return;
        }
        if ('updateComponents' in message) {
            const upd = message.updateComponents as A2uiUpdateComponents;
            const live = surfacesSignal().get(upd.surfaceId);
            if (live) {
                const components = new Map(live.components);
                const state = surfaceStatesSignal().get(upd.surfaceId);
                const views = new Map(state?.componentViews ?? []);
                for (const c of upd.components) {
                    components.set(c.id, c);
                    views.set(c.id, projectView(c));
                }
                const surface: A2uiSurface = { ...live, components };
                publish(surface, refreshViews(views, surface.dataModel));
                return;
            }
            const b = bufferOf(upd.surfaceId);
            for (const c of upd.components) {
                b.components.set(c.id, c);
                b.componentViews.set(c.id, projectView(c));
            }
            tryCommit(upd.surfaceId);
            return;
        }
        if ('updateDataModel' in message) {
            const upd = message.updateDataModel as A2uiUpdateDataModel;
            const delta = { path: upd.path, value: upd.value, del: !('value' in upd) || upd.value === undefined };
            const live = surfacesSignal().get(upd.surfaceId);
            if (live) {
                const dataModel = applyDataModelDelta(live.dataModel, delta);
                const surface: A2uiSurface = { ...live, dataModel };
                const state = surfaceStatesSignal().get(upd.surfaceId);
                publish(surface, refreshViews(state?.componentViews ?? new Map(), dataModel));
            }
            else {
                bufferOf(upd.surfaceId).dataModelDeltas.push(delta);
            }
            return;
        }
        if ('deleteSurface' in message) {
            const del = message.deleteSurface as A2uiDeleteSurface;
            buffers.delete(del.surfaceId);
            const next = new Map(surfacesSignal());
            next.delete(del.surfaceId);
            surfacesSignal.set(next);
            const nextStates = new Map(surfaceStatesSignal());
            nextStates.delete(del.surfaceId);
            surfaceStatesSignal.set(nextStates);
            return;
        }
    }
    function surface(surfaceId: string): Signal<A2uiSurface | undefined> {
        return computed(() => surfacesSignal().get(surfaceId));
    }
    function surfaceState(surfaceId: string): Signal<A2uiSurfaceState | undefined> {
        return computed(() => surfaceStatesSignal().get(surfaceId));
    }
    const liveTools = new Set<string>();
    function applyPartialArgs(toolCallId: string, envelopes: readonly A2uiMessage[]): void {
        liveTools.add(toolCallId);
        for (const env of envelopes) {
            apply(env);
        }
    }
    function isPartialLive(toolCallId: string): boolean {
        return liveTools.has(toolCallId);
    }
    return {
        apply,
        applyPartialArgs,
        isPartialLive,
        surfaces: surfacesSignal.asReadonly(),
        surface,
        surfaceStates: surfaceStatesSignal.asReadonly(),
        surfaceState,
    };
}

export function createAgentRef<TState>(debugName?: string): AgentRef<TState> {
    return { token: new InjectionToken<Agent<TState>>(debugName ?? 'ThreadplaneAgent') };
}

export function createContentClassifier(): ContentClassifier {
    const typeSignal = signal<ContentType>('pending');
    const markdownSignal = signal<string>('');
    const specSignal = signal<Spec | null>(null);
    const elementStatesSignal = signal<Map<string, ElementAccumulationState>>(new Map());
    const streamingSignal = signal<boolean>(false);
    const errorsSignal = signal<string[]>([]);
    let processedLength = 0;
    let previousContent = '';
    let store: ParseTreeStore | null = null;
    let jsonStartIndex = 0;
    let a2uiParser: A2uiMessageParser | null = null;
    let a2uiStore: A2uiSurfaceStore | null = null;
    const a2uiSurfacesSignal = signal<Map<string, A2uiSurface>>(new Map());
    const a2uiSurfaceStatesSignal = signal<Map<string, A2uiSurfaceState>>(new Map());
    function detectType(content: string): ContentType {
        for (let i = 0; i < content.length; i++) {
            const ch = content[i];
            if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r')
                continue;
            if (ch === '{') {
                return 'json-render';
            }
            if (ch === '-') {
                if (content.startsWith(A2UI_PREFIX, i)) {
                    return 'a2ui';
                }
                const remaining = content.length - i;
                if (remaining < A2UI_PREFIX.length) {
                    const candidate = content.slice(i);
                    if (A2UI_PREFIX.startsWith(candidate)) {
                        return 'pending';
                    }
                    return 'markdown';
                }
                return 'markdown';
            }
            return 'markdown';
        }
        return 'pending';
    }
    function initJsonStore(jsonContent: string): void {
        const parser = createPartialJsonParser();
        store = createParseTreeStore(parser);
        if (jsonContent.length > 0) {
            store.push(jsonContent);
        }
        syncJsonSignals();
    }
    function syncJsonSignals(): void {
        if (!store)
            return;
        specSignal.set(store.spec());
        elementStatesSignal.set(store.elementStates());
        const spec = store.spec();
        if (spec) {
            streamingSignal.set(isStillStreaming());
        }
        else {
            streamingSignal.set(true);
        }
    }
    function isStillStreaming(): boolean {
        if (!store)
            return false;
        const states = store.elementStates();
        for (const state of states.values()) {
            if (state.streaming)
                return true;
        }
        const spec = store.spec();
        if (!spec || !spec.root || !spec.elements)
            return true;
        return false;
    }
    function resetState(): void {
        typeSignal.set('pending');
        markdownSignal.set('');
        specSignal.set(null);
        elementStatesSignal.set(new Map());
        streamingSignal.set(false);
        errorsSignal.set([]);
        processedLength = 0;
        store = null;
        jsonStartIndex = 0;
        a2uiParser = null;
        a2uiStore = null;
        a2uiSurfacesSignal.set(new Map());
        a2uiSurfaceStatesSignal.set(new Map());
    }
    function update(content: string): void {
        untracked(() => {
            if (!content.startsWith(previousContent)) {
                resetState();
            }
            previousContent = content;
            const currentType = typeSignal();
            if (currentType === 'pending') {
                const detected = detectType(content);
                if (detected === 'pending')
                    return;
                typeSignal.set(detected);
                if (detected === 'markdown') {
                    markdownSignal.set(content);
                    processedLength = content.length;
                }
                else if (detected === 'json-render') {
                    streamingSignal.set(true);
                    jsonStartIndex = 0;
                    for (let i = 0; i < content.length; i++) {
                        if (content[i] !== ' ' && content[i] !== '\t' && content[i] !== '\n' && content[i] !== '\r') {
                            jsonStartIndex = i;
                            break;
                        }
                    }
                    const jsonContent = content.slice(jsonStartIndex);
                    try {
                        initJsonStore(jsonContent);
                    }
                    catch (err) {
                        errorsSignal.update(prev => [...prev, err instanceof Error ? err.message : String(err)]);
                    }
                    processedLength = content.length;
                }
                else if (detected === 'a2ui') {
                    streamingSignal.set(true);
                    a2uiParser = createA2uiMessageParser();
                    a2uiStore = createA2uiSurfaceStore();
                    jsonStartIndex = content.indexOf(A2UI_PREFIX) + A2UI_PREFIX.length;
                    const a2uiContent = content.slice(jsonStartIndex);
                    if (a2uiContent.length > 0) {
                        try {
                            const msgs = a2uiParser.push(a2uiContent);
                            for (const msg of msgs)
                                a2uiStore.apply(msg);
                            a2uiSurfacesSignal.set(a2uiStore.surfaces());
                            a2uiSurfaceStatesSignal.set(a2uiStore.surfaceStates());
                        }
                        catch (err) {
                            errorsSignal.update(prev => [...prev, err instanceof Error ? err.message : String(err)]);
                        }
                    }
                    processedLength = content.length;
                }
                return;
            }
            const delta = content.slice(processedLength);
            processedLength = content.length;
            if (delta.length === 0)
                return;
            if (currentType === 'markdown') {
                markdownSignal.set(content);
            }
            else if (currentType === 'json-render') {
                if (store) {
                    try {
                        store.push(delta);
                        syncJsonSignals();
                    }
                    catch (err) {
                        errorsSignal.update(prev => [...prev, err instanceof Error ? err.message : String(err)]);
                    }
                }
            }
            else if (currentType === 'a2ui') {
                if (a2uiParser && a2uiStore) {
                    try {
                        const msgs = a2uiParser.push(delta);
                        for (const msg of msgs)
                            a2uiStore.apply(msg);
                        a2uiSurfacesSignal.set(a2uiStore.surfaces());
                        a2uiSurfaceStatesSignal.set(a2uiStore.surfaceStates());
                    }
                    catch (err) {
                        errorsSignal.update(prev => [...prev, err instanceof Error ? err.message : String(err)]);
                    }
                }
            }
            if (isTraceEnabled()) {
                trace('classifier.update', { contentLength: content.length, type: typeSignal() });
            }
        });
    }
    function dispose(): void {
        store = null;
        a2uiParser = null;
        a2uiStore = null;
    }
    return {
        update,
        type: typeSignal.asReadonly(),
        markdown: markdownSignal.asReadonly(),
        spec: specSignal.asReadonly(),
        elementStates: elementStatesSignal.asReadonly(),
        a2uiSurfaces: a2uiSurfacesSignal.asReadonly(),
        a2uiSurfaceStates: a2uiSurfaceStatesSignal.asReadonly(),
        streaming: streamingSignal.asReadonly(),
        errors: errorsSignal.asReadonly(),
        dispose,
    };
}

export function createParseTreeStore(parser: PartialJsonParser): ParseTreeStore {
    const specSignal = signal<Spec | null>(null);
    const elementStatesSignal = signal<Map<string, ElementAccumulationState>>(new Map());
    function computeElementStates(materialized: any): Map<string, ElementAccumulationState> {
        const states = new Map<string, ElementAccumulationState>();
        if (!materialized || typeof materialized !== 'object' || !materialized.elements) {
            return states;
        }
        const elements = materialized.elements as Record<string, any>;
        const elementsNode = parser.getByPath('/elements') as JsonObjectNode | null;
        for (const [key, el] of Object.entries(elements)) {
            if (!el || typeof el !== 'object')
                continue;
            let streaming = true;
            if (elementsNode) {
                const elNode = elementsNode.children.get(key);
                if (elNode && elNode.status === 'complete') {
                    streaming = false;
                }
            }
            states.set(key, {
                hasType: 'type' in el && el.type !== undefined,
                hasProps: 'props' in el && el.props !== undefined,
                hasChildren: 'children' in el && el.children !== undefined,
                streaming,
            });
        }
        return states;
    }
    function push(chunk: string): void {
        parser.push(chunk);
        if (parser.root) {
            const materialized = materialize(parser.root);
            specSignal.set(materialized as Spec);
            elementStatesSignal.set(computeElementStates(materialized));
        }
    }
    return {
        push,
        spec: specSignal.asReadonly(),
        elementStates: elementStatesSignal.asReadonly(),
    };
}

export function createPartialArgsBridge(store: A2uiSurfaceStore): PartialArgsBridge {
    const states = new Map<string, BridgeState>();
    function stateOf(toolCallId: string): BridgeState {
        let s = states.get(toolCallId);
        if (!s) {
            s = {
                parser: createPartialJsonParser(),
                args: '',
                dispatchedCount: 0,
                createDispatched: new Set(),
                poisoned: false,
            };
            states.set(toolCallId, s);
        }
        return s;
    }
    function push(toolCallId: string, argsSoFar: string): void {
        const state = stateOf(toolCallId);
        if (state.poisoned)
            return;
        if (argsSoFar === state.args)
            return;
        if (!isValidJsonPrefix(argsSoFar)) {
            state.poisoned = true;
            return;
        }
        try {
            if (!argsSoFar.startsWith(state.args)) {
                state.parser = createPartialJsonParser();
                state.args = '';
            }
            state.parser.push(argsSoFar.slice(state.args.length));
            state.args = argsSoFar;
        }
        catch {
            state.poisoned = true;
            return;
        }
        const rootNode = state.parser.getByPath('/');
        if (!rootNode)
            return;
        const materialised = materialize(rootNode) as Record<string, unknown> | null;
        if (!materialised || typeof materialised !== 'object')
            return;
        const envelopes = normalizeEnvelopeArgs(materialised);
        if (!envelopes)
            return;
        const newEnvelopes: A2uiMessage[] = [];
        for (let i = state.dispatchedCount; i < envelopes.length; i++) {
            const env = envelopes[i] as A2uiMessage;
            if (!isStructurallyComplete(env)) {
                break;
            }
            if ('createSurface' in env) {
                state.createDispatched.add(env.createSurface.surfaceId);
            }
            else if ('updateComponents' in env) {
                const surfaceId = env.updateComponents.surfaceId;
                if (!state.createDispatched.has(surfaceId)) {
                    state.createDispatched.add(surfaceId);
                    newEnvelopes.push({
                        version: A2UI_WIRE_VERSION,
                        createSurface: { surfaceId, catalogId: A2UI_BASIC_CATALOG_ID },
                    });
                }
            }
            newEnvelopes.push(env);
            state.dispatchedCount = i + 1;
        }
        if (newEnvelopes.length > 0) {
            store.applyPartialArgs(toolCallId, newEnvelopes);
        }
    }
    function isPoisoned(toolCallId: string): boolean {
        return stateOf(toolCallId).poisoned;
    }
    return { push, isPoisoned };
}

export function defaultInterruptedClientToolResult(toolCallId: string): ClientToolResult {
    return {
        ok: false,
        error: `client tool execution interrupted before completion: ${toolCallId}`,
    };
}

export function deriveDomain(url?: string): string | null {
    if (!url)
        return null;
    try {
        return new URL(url).hostname.replace(/^www\./, '');
    }
    catch {
        return null;
    }
}

export function deriveJsonSchema(toolName: string, schema: StandardSchemaV1): Record<string, unknown> {
    try {
        return toJSONSchema(schema as never) as Record<string, unknown>;
    }
    catch (err) {
        throw new Error(`client tool "${toolName}": could not derive a JSON Schema from its schema. ` +
            `Use a Zod schema (recommended) or an already-JSON-Schema-compatible validator. ` +
            `Underlying error: ${err instanceof Error ? err.message : String(err)}`);
    }
}

export function deriveMonogram(c: Citation): string {
    const seed = deriveDomain(c.url) ?? c.title ?? '';
    const ch = seed.trim().charAt(0);
    return ch ? ch.toUpperCase() : '?';
}

export function deriveSourceType(c: Citation): string {
    const explicit = c.sourceType?.trim();
    if (explicit)
        return explicit;
    return c.url ? 'web' : 'unknown';
}

export function emitBinding(host: RenderHost, bindings: Record<string, string> | undefined, prop: string, value: unknown): void {
    const path = bindings?.[prop];
    if (path) {
        host.set(path, value);
    }
}

export async function executeFunctionTool(def: AnyFunctionToolDef, rawArgs: unknown, context: FunctionToolHandlerContext = { signal: defaultSignal }): Promise<ClientToolResult> {
    const v = await validateArgs(def.schema, rawArgs);
    if (!v.ok)
        return { ok: false, error: `invalid arguments: ${(v as {
                error: string;
            }).error}` };
    try {
        const value = await def.handler((v as {
            value: unknown;
        }).value as never, context);
        return { ok: true, value };
    }
    catch (err) {
        return { ok: false, error: err instanceof Error ? err.message : String(err) };
    }
}

export function extractErrorMessage(error: unknown): string | null {
    if (!error)
        return null;
    if (error instanceof Error)
        return error.message;
    if (typeof error === 'string')
        return error;
    return String(error);
}

export function formatDuration(ms: number): string {
    if (!Number.isFinite(ms) || ms < 1000)
        return '<1s';
    const totalSeconds = Math.floor(ms / 1000);
    if (totalSeconds < 60)
        return `${totalSeconds}s`;
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds - minutes * 60;
    return `${minutes}m ${seconds}s`;
}

export function formatPublished(value?: string | number | Date): string | null {
    if (value == null)
        return null;
    const d = value instanceof Date ? value : new Date(value);
    if (Number.isNaN(d.getTime()))
        return null;
    return d.toLocaleDateString(undefined, { year: 'numeric', month: 'short' });
}

export function getInterrupt(agent: Agent): AgentInterrupt | undefined {
    return agent.interrupt?.();
}

export function getMessageType(message: Message): MessageTemplateType {
    switch (message.role) {
        case 'user':
            return 'human';
        case 'assistant':
            return 'ai';
        case 'tool':
            return 'tool';
        case 'system':
            return 'system';
        default:
            return 'ai';
    }
}

export function injectThreadRouting(config: ThreadRoutingConfig): void {
    const router = inject(Router);
    const fromUrl = config.threadIdFromUrl ?? defaultFromUrl;
    const toCommands = config.toCommands ?? defaultToCommands;
    const extras: NavigationExtras = config.navigationExtras ?? { queryParamsHandling: 'preserve' };
    const urlThreadId = toSignal(router.events.pipe(filter((e): e is NavigationEnd => e instanceof NavigationEnd), map((e) => fromUrl(e.urlAfterRedirects)), startWith(fromUrl(router.url))), { initialValue: fromUrl(router.url) });
    config.threadId.set(urlThreadId());
    effect(() => {
        const urlId = urlThreadId();
        if (urlId !== untracked(() => config.threadId()))
            config.threadId.set(urlId);
    });
    effect(() => {
        const id = config.threadId();
        const urlId = untracked(() => urlThreadId());
        if (id !== urlId)
            void router.navigate(toCommands(id), extras);
    });
    if (config.validate) {
        const validate = config.validate;
        let lastValidated: string | null = null;
        effect(() => {
            const id = urlThreadId();
            if (!id || id === lastValidated)
                return;
            lastValidated = id;
            void validate(id).then((ok) => {
                if (!ok && untracked(() => urlThreadId()) === id) {
                    void router.navigate(toCommands(null), { ...extras, replaceUrl: true });
                }
            });
        });
    }
}

export function isAbortError(raw: unknown): boolean {
    return raw instanceof Error && (raw.name === 'AbortError' || /\babort/i.test(raw.message));
}

export function isAssistantMessage(m: Message): m is Message & {
    role: 'assistant';
} {
    return m.role === 'assistant';
}

export function isFunctionCall(value: unknown): value is {
    call: string;
    args?: Record<string, unknown>;
} {
    return typeof value === 'object' && value !== null
        && 'call' in value && typeof (value as {
        call: unknown;
    }).call === 'string';
}

export function isPathRef(value: unknown): value is {
    path: string;
} {
    return typeof value === 'object' && value !== null
        && 'path' in value && typeof (value as {
        path: unknown;
    }).path === 'string';
}

export function isSystemMessage(m: Message): m is Message & {
    role: 'system';
} {
    return m.role === 'system';
}

export function isToolMessage(m: Message): m is Message & {
    role: 'tool';
} {
    return m.role === 'tool';
}

export function isTyping(agent: Agent): boolean {
    if (!agent.isLoading())
        return false;
    const msgs = agent.messages();
    if (msgs.length === 0)
        return true;
    const last = msgs[msgs.length - 1];
    if (last.role === 'user')
        return true;
    if (last.role === 'assistant') {
        return typeof last.content === 'string'
            ? !last.content
            : last.content.length === 0;
    }
    return false;
}

export function isUserMessage(m: Message): m is Message & {
    role: 'user';
} {
    return m.role === 'user';
}

export function markdownDocument(content: string, delivery: MessageDelivery, suffix = ''): StreamingMarkdownDocument {
    return {
        generation: delivery.generation + suffix,
        phase: delivery.phase,
        content,
    };
}

export function messageContent(message: {
    content: unknown;
}): string {
    return extractText(message.content);
}

export function mockAgent(opts: MockAgentOptions = {}): MockAgent {
    const messages = signal<Message[]>(opts.messages ?? []);
    const status = signal<AgentStatus>(opts.status ?? 'idle');
    const isLoading = signal<boolean>(opts.isLoading ?? false);
    const error = signal<AgentError | undefined>(opts.error ?? undefined);
    const toolCalls = signal<ToolCall[]>(opts.toolCalls ?? []);
    const state = signal<Record<string, unknown>>(opts.state ?? {});
    const interrupt = opts.withInterrupt
        ? signal<AgentInterrupt | undefined>(undefined)
        : undefined;
    const subagents = opts.withSubagents
        ? signal<Map<string, Subagent>>(new Map())
        : undefined;
    const history = opts.history
        ? signal<AgentCheckpoint[]>(opts.history)
        : undefined;
    const submitCalls: MockAgent['submitCalls'] = [];
    let stopCount = 0;
    const streamStartedAt = signal<number | null>(null);
    const agent: MockAgent = {
        messages, status, isLoading, error, toolCalls, state,
        ...(interrupt ? { interrupt } : {}),
        ...(subagents ? { subagents } : {}),
        ...(history ? { history } : {}),
        lifecycle: { streamStartedAt: streamStartedAt.asReadonly() },
        _internal: { streamStartedAt },
        events$: opts.events$ ?? EMPTY,
        submit: async (input, submitOpts) => { submitCalls.push({ input, opts: submitOpts }); },
        stop: async () => { stopCount++; },
        retry: async () => { return; },
        regenerate: async (assistantMessageIndex: number) => {
            const current = messages();
            messages.set(current.slice(0, assistantMessageIndex));
            submitCalls.push({ input: { regenerate: { assistantMessageIndex } } as never, opts: undefined });
        },
        submitCalls,
        get stopCount() { return stopCount; },
    };
    return agent;
}

export function monogramColor(c: Citation): string {
    const seed = deriveDomain(c.url) ?? c.title ?? '?';
    return `hsl(${monogramHue(seed)} 60% 45%)`;
}

export function monogramHue(seed: string): number {
    let h = 0;
    for (let i = 0; i < seed.length; i++) {
        h = (h * 31 + seed.charCodeAt(i)) % 360;
    }
    return h;
}

export function normalizeEnvelopeArgs(args: Record<string, unknown> | null | undefined): unknown[] | null {
    if (!args || typeof args !== 'object' || Array.isArray(args))
        return null;
    if (Array.isArray((args as {
        envelopes?: unknown;
    }).envelopes)) {
        return (args as {
            envelopes: unknown[];
        }).envelopes;
    }
    if (Array.isArray((args as {
        envelope?: unknown;
    }).envelope)) {
        return (args as {
            envelope: unknown[];
        }).envelope;
    }
    const keys = Object.keys(args);
    if (keys.length === 0)
        return null;
    if (keys.every((k) => /^\d+$/.test(k))) {
        return keys
            .map((k) => Number(k))
            .sort((a, b) => a - b)
            .map((k) => (args as Record<string, unknown>)[String(k)]);
    }
    if (ENVELOPE_KEYS.some((k) => k in args)) {
        return [args];
    }
    return null;
}

export function normalizeViewEntry(entry: Type<unknown> | A2uiViewEntry): A2uiViewEntry {
    if (typeof entry === 'function')
        return { component: entry };
    return entry;
}

export function renderMarkdown(content: string, sanitizer: DomSanitizer): SafeHtml {
    if (markedParse) {
        const html = markedParse(content);
        return sanitizer.bypassSecurityTrustHtml(sanitizer.sanitize(SecurityContext.HTML, html) ?? '');
    }
    return sanitizer.bypassSecurityTrustHtml(plainTextToHtml(content));
}

export function selectPendingClientToolCalls(input: SelectPendingClientToolCallsInput): readonly ToolCall[] {
    if (input.isLoading)
        return [];
    return input.toolCalls.filter((tc) => input.catalogNames.has(tc.name) &&
        tc.result === undefined &&
        !input.resolvedIds.has(tc.id));
}

export function shouldClaimBeforeExecute(def: AnyFunctionToolDef): boolean {
    return def.idempotent !== true;
}

export function startClientToolExecutor(agent: Agent, registry: ClientToolRegistry, options: ClientToolExecutorOptions = {}): void {
    const cap = agent.clientTools;
    if (!cap)
        return;
    const destroyRef = inject(DestroyRef);
    const inFlight = new Map<string, AbortController>();
    const abortAll = (): void => {
        for (const controller of inFlight.values()) {
            controller.abort();
        }
    };
    let patch = patchedAgents.get(agent);
    if (!patch) {
        const originalStop = agent.stop;
        const boundStop = originalStop.bind(agent);
        const aborts = new Set<() => void>();
        const wrapper = async (): Promise<void> => {
            for (const abort of aborts)
                abort();
            await boundStop();
        };
        patch = { aborts, originalStop, wrapper };
        patchedAgents.set(agent, patch);
        agent.stop = wrapper;
    }
    const registration = patch;
    registration.aborts.add(abortAll);
    destroyRef.onDestroy(() => {
        registration.aborts.delete(abortAll);
        if (registration.aborts.size === 0 && patchedAgents.get(agent) === registration) {
            if (agent.stop === registration.wrapper)
                agent.stop = registration.originalStop;
            patchedAgents.delete(agent);
        }
    });
    destroyRef.onDestroy(abortAll);
    const settleToolCall = options.settleToolCall ?? ((toolCall, result) => cap.resolve(toolCall.id, result));
    const settleWithoutContinuing = options.settleWithoutContinuing ??
        ((toolCall: ToolCall, result: ClientToolResult) => {
            if (!cap.settle) {
                console.warn(`Client tool "${toolCall.name}" was cancelled but the agent capability does not implement settle(); the result cannot be recorded without starting a run.`);
                return;
            }
            cap.settle(toolCall.id, result);
            void Promise.resolve(cap.flush?.()).catch(() => undefined);
        });
    effect(() => {
        for (const tc of cap.pending()) {
            const def = registry[tc.name];
            if (!def || def.kind !== 'function')
                continue;
            if (inFlight.has(tc.id))
                continue;
            if (options.shouldExecuteToolCall && !options.shouldExecuteToolCall(tc))
                continue;
            const controller = new AbortController();
            inFlight.set(tc.id, controller);
            void runFunctionTool({
                def,
                toolCall: tc,
                rawArgs: tc.args,
                toolCallId: tc.id,
                controller,
                executionGuard: options.executionGuard,
                settleToolCall,
                settleWithoutContinuing,
            }).finally(() => {
                inFlight.delete(tc.id);
            });
        }
    });
}

export function staticDelivery(messageId: string) {
    return completeDelivery(messageId, 'success');
}

export function statusColor(status: SubagentStatus): string {
    switch (status) {
        case 'pending': return 'background: var(--tplane-chat-surface-alt); color: var(--tplane-chat-text-muted);';
        case 'running': return 'background: var(--tplane-chat-warning-bg); color: var(--tplane-chat-warning-text);';
        case 'complete': return 'color: var(--tplane-chat-success);';
        case 'error': return 'background: var(--tplane-chat-error-bg); color: var(--tplane-chat-error-text);';
    }
}

export function streamingDelivery(generation: string) {
    return { generation, phase: 'streaming' } as const satisfies MessageDelivery;
}

export function submitMessage(agent: Agent, text: string): string | null {
    const trimmed = text.trim();
    if (!trimmed || agent.isInputBlocked?.())
        return null;
    void agent.submit({ message: trimmed });
    return trimmed;
}

export function toAgentError(raw: unknown): AgentError {
    if (raw instanceof AgentError)
        return raw;
    if (isAbortError(raw))
        return make('aborted', false, raw);
    const structured = structuredStatus(raw);
    if (structured !== undefined)
        return classifyByStatus(structured, raw);
    if (isConnectionError(raw))
        return make('connection', true, raw);
    const httpStatus = httpStatusFromMessage(raw);
    if (httpStatus !== undefined)
        return classifyByStatus(httpStatus, raw);
    const msg = raw instanceof Error && raw.message ? raw.message : 'Something went wrong. You can try again.';
    return make('server', true, raw, undefined, msg);
}

export function toClientToolSpecs(registry: ClientToolRegistry): ClientToolSpec[] {
    return Object.entries(registry).map(([name, def]) => ({
