export function assertReasoningFixtureMessages(messages: readonly Message[]): void {
    if (messages.length !== 1) {
        throw new Error(`Expected exactly 1 message, got ${messages.length}: ${JSON.stringify(messages)}`);
    }
    const m = messages[0];
    if (m.role !== 'assistant') {
        throw new Error(`Expected assistant role, got ${m.role}`);
    }
    if (m.content !== REASONING_FIXTURE_RESPONSE) {
        throw new Error(`Expected content ${JSON.stringify(REASONING_FIXTURE_RESPONSE)}, got ${JSON.stringify(m.content)}`);
    }
    if (m.reasoning !== REASONING_FIXTURE_REASONING) {
        throw new Error(`Expected reasoning ${JSON.stringify(REASONING_FIXTURE_REASONING)}, got ${JSON.stringify(m.reasoning)}`);
    }
    if (typeof m.reasoningDurationMs !== 'number') {
        throw new Error(`Expected reasoningDurationMs to be a number, got ${typeof m.reasoningDurationMs}`);
    }
    if (m.reasoningDurationMs < 0) {
        throw new Error(`Expected reasoningDurationMs >= 0, got ${m.reasoningDurationMs}`);
    }
}

export function runAgentConformance(label: string, factory: () => Agent): void {
    describe(`${label} — Agent conformance`, () => {
        it('exposes required core signals', () => {
            const a = factory();
            expect(typeof a.messages).toBe('function');
            expect(typeof a.status).toBe('function');
            expect(typeof a.isLoading).toBe('function');
            expect(typeof a.error).toBe('function');
            expect(typeof a.toolCalls).toBe('function');
            expect(typeof a.state).toBe('function');
        });
        it('messages() returns an array', () => {
            expect(Array.isArray(factory().messages())).toBe(true);
        });
        it('toolCalls() returns an array', () => {
            expect(Array.isArray(factory().toolCalls())).toBe(true);
        });
        it('state() returns a plain object', () => {
            const v = factory().state();
            expect(typeof v).toBe('object');
            expect(v).not.toBeNull();
        });
        it('status() returns one of the allowed values', () => {
            expect(['idle', 'running', 'error']).toContain(factory().status());
        });
        it('isLoading() is true only when status === "running"', () => {
            const a = factory();
            if (a.isLoading()) {
                expect(a.status()).toBe('running');
            }
        });
        it('submit() returns a Promise', () => {
            const result = factory().submit({ message: 'test' });
            expect(result).toBeInstanceOf(Promise);
        });
        it('stop() returns a Promise', () => {
            const result = factory().stop();
            expect(result).toBeInstanceOf(Promise);
        });
        it('events$ is an Observable-like with .subscribe', () => {
            const agent = factory();
            expect(typeof agent.events$.subscribe).toBe('function');
        });
    });
}

export function runAgentWithHistoryConformance(label: string, factory: (seed?: {
    history?: AgentCheckpoint[];
}) => AgentWithHistory): void {
    runAgentConformance(label, () => factory());
    describe(`${label} — history`, () => {
        it('exposes a history signal', () => {
            const agent = factory();
            expect(typeof agent.history).toBe('function');
            expect(Array.isArray(agent.history())).toBe(true);
        });
        it('reflects seeded checkpoints', () => {
            const seed: AgentCheckpoint[] = [
                { id: 'c1', label: 'Step 1', values: { foo: 1 } },
                { id: 'c2', label: 'Step 2', values: { foo: 2 } },
            ];
            const agent = factory({ history: seed });
            const entries = agent.history();
            expect(entries).toHaveLength(2);
            expect(entries[0].id).toBe('c1');
            expect(entries[1].values).toEqual({ foo: 2 });
        });
    });
}

export function runInterruptConformance(label: string, factory: () => InterruptConformanceHarness, options: {
    restoration?: boolean;
} = {}): void {
    describe(`${label} — interrupt conformance`, () => {
        for (const [name, scenario] of interruptConformanceScenarios(factory, options)) {
            it(name, scenario);
        }
    });
}

