export class FakeStreamTransport implements AgentTransport {
    private readonly tokens: string[];
    private readonly reasoningTokens: string[];
    private readonly delayMs: number;
    constructor(config: FakeAgentConfig = {}) {
        this.tokens = config.tokens ?? DEFAULT_TOKENS;
        this.reasoningTokens = config.reasoningTokens ?? [];
        this.delayMs = config.delayMs ?? 60;
    }
    async *stream(_assistantId: string, _threadId: string | null, _payload: unknown, signal: AbortSignal, _options?: LangGraphSubmitOptions): AsyncIterable<StreamEvent> {
        const id = 'fake-ai-1';
        let reasoning = '';
        for (const chunk of this.reasoningTokens) {
            if (signal.aborted)
                return;
            reasoning += chunk;
            yield {
                type: 'messages',
                messages: [
                    { id, type: 'ai', content: '', additional_kwargs: { reasoning_content: reasoning } },
                ],
            } as unknown as StreamEvent;
            if (this.delayMs > 0)
                await delay(this.delayMs);
        }
        let content = '';
        for (const tok of this.tokens) {
            if (signal.aborted)
                return;
            content += tok;
            yield {
                type: 'messages',
                messages: [{ id, type: 'ai', content }],
            } as unknown as StreamEvent;
            if (this.delayMs > 0)
                await delay(this.delayMs);
        }
    }
    async createQueuedRun(_assistantId: string, threadId: string, payload: unknown, _signal: AbortSignal, options?: LangGraphSubmitOptions): Promise<AgentQueueEntry> {
        return {
            id: 'fake-queued-run',
            threadId,
            values: payload,
            options: { ...options, multitaskStrategy: 'enqueue' },
            createdAt: new Date(),
        };
    }
    async cancelRun(_threadId: string, _runId: string, _signal: AbortSignal): Promise<void> {
        return;
    }
    async getHistory(_threadId: string, _signal: AbortSignal): Promise<ThreadState[]> {
        return [];
    }
    async *joinStream(): AsyncIterable<StreamEvent> {
        yield* [];
    }
}

export class FetchStreamTransport implements AgentTransport {
    private client: Client;
    private onThreadId?: (id: string) => void;
    private readonly protectErrors: boolean;
    private readonly reportOperationFailure?: RuntimeOperationFailureReporter;
    readonly protectsOperationErrors: boolean;
    constructor(apiUrl: string, onThreadId?: (id: string) => void, clientOptions?: LangGraphClientOptions, reportOperationFailure?: RuntimeOperationFailureReporter) {
        this.protectErrors = clientOptions?.defaultHeaders !== undefined || reportOperationFailure !== undefined;
        this.protectsOperationErrors = this.protectErrors;
        this.reportOperationFailure = reportOperationFailure;
        this.client = this.protectErrors
            ? ɵcreateProtectedLangGraphClient(apiUrl, clientOptions, createLangGraphRuntimeFetch(reportOperationFailure))
            : createLangGraphClient(apiUrl, clientOptions);
        this.onThreadId = onThreadId;
    }
    async *stream(assistantId: string, threadId: string | null, payload: unknown, signal: AbortSignal, options?: LangGraphSubmitOptions): AsyncIterable<StreamEvent> {
        let thread = threadId;
        if (!thread) {
            try {
                const t = await this.client.threads.create();
                thread = t.thread_id;
            }
            catch (error) {
                this.rethrowOperationError(error, signal);
            }
            try {
                this.onThreadId?.(thread);
            }
            catch (error) {
                this.rethrowLocalError(error, signal);
            }
        }
        let runPayload: ReturnType<typeof buildRunPayload>;
        try {
            runPayload = buildRunPayload(payload, signal, options);
        }
        catch (error) {
            return this.rethrowLocalError(error, signal);
        }
        let run: ReturnType<Client['runs']['stream']>;
        try {
            run = this.client.runs.stream(thread, assistantId, runPayload);
        }
        catch (error) {
            this.rethrowOperationError(error, signal);
        }
        yield* this.iterateSdkRun(run, signal);
    }
    async *joinStream(threadId: string, runId: string, lastEventId: string | undefined, signal: AbortSignal): AsyncIterable<StreamEvent> {
        let run: ReturnType<Client['runs']['joinStream']>;
        try {
            run = this.client.runs.joinStream(threadId, runId, {
                signal,
                ...(lastEventId !== undefined ? { lastEventId } : {}),
            });
        }
        catch (error) {
            this.rethrowOperationError(error, signal);
        }
        yield* this.iterateSdkRun(run, signal);
    }
    async createQueuedRun(assistantId: string, threadId: string, payload: unknown, signal: AbortSignal, options?: LangGraphSubmitOptions): Promise<AgentQueueEntry> {
        let runPayload: ReturnType<typeof buildRunPayload> & {
            multitaskStrategy: 'enqueue';
        };
        try {
            runPayload = {
                ...buildRunPayload(payload, signal, options),
                multitaskStrategy: 'enqueue',
            };
        }
        catch (error) {
            return this.rethrowLocalError(error, signal);
        }
        let run: Awaited<ReturnType<Client['runs']['create']>>;
        try {
            run = await this.client.runs.create(threadId, assistantId, runPayload);
        }
        catch (error) {
            return this.rethrowOperationError(error, signal);
        }
        try {
            return {
                id: run.run_id,
                threadId: run.thread_id ?? threadId,
                values: payload,
                options: { multitaskStrategy: 'enqueue', signal },
                createdAt: run.created_at ? new Date(run.created_at) : new Date(),
            };
        }
        catch (error) {
            return this.rethrowLocalError(error, signal);
        }
    }
    async cancelRun(threadId: string, runId: string, signal: AbortSignal): Promise<void> {
        try {
            await this.client.runs.cancel(threadId, runId, false, 'interrupt', { signal });
        }
        catch (error) {
            this.rethrowOperationError(error, signal);
        }
    }
    async getHistory(threadId: string, signal: AbortSignal): Promise<ThreadState[]> {
        try {
            return await this.client.threads.getHistory(threadId, { signal });
        }
        catch (error) {
            return this.rethrowOperationError(error, signal);
        }
    }
    async updateState(threadId: string, values: Record<string, unknown>, _signal: AbortSignal, options?: {
        asNode?: string;
    }): Promise<void> {
        const body: {
            values: Record<string, unknown>;
            asNode?: string;
        } = { values };
        if (options?.asNode !== undefined) {
            body.asNode = options.asNode;
        }
        try {
            await this.client.threads.updateState(threadId, body);
        }
        catch (error) {
            this.rethrowOperationError(error, _signal);
        }
    }
    private rethrowOperationError(error: unknown, signal: AbortSignal): never {
        if (!this.protectErrors)
            throw error;
        return projectLangGraphOperationFailure(error, signal, this.reportOperationFailure);
    }
    private rethrowLocalError(error: unknown, signal: AbortSignal): never {
        if (!this.protectErrors)
            throw error;
        return projectLangGraphOperationFailure(error, signal, undefined);
    }
    private async *iterateSdkRun(run: ReturnType<Client['runs']['stream']> | ReturnType<Client['runs']['joinStream']>, signal: AbortSignal): AsyncIterable<StreamEvent> {
        let iterator: AsyncIterator<{
            event: string;
            data: unknown;
        }>;
        try {
            iterator = run[Symbol.asyncIterator]();
        }
        catch (error) {
            return this.rethrowOperationError(error, signal);
        }
        let completed = false;
        let failed = false;
        try {
            while (true) {
                let next: IteratorResult<{
                    event: string;
                    data: unknown;
                }>;
                try {
                    next = await iterator.next();
                }
                catch (error) {
                    return this.rethrowOperationError(error, signal);
                }
                if (next.done) {
                    completed = true;
                    return;
                }
                try {
                    yield normalizeSdkEvent(next.value.event as StreamEvent['type'], next.value.data);
                }
                catch (error) {
                    return this.rethrowLocalError(error, signal);
                }
            }
        }
        catch (error) {
            failed = true;
            throw error;
        }
        finally {
            if (!completed) {
                try {
                    await iterator.return?.();
                }
                catch (error) {
                    if (!failed)
                        this.rethrowOperationError(error, signal);
                }
            }
        }
    }
}

