@Injectable({ providedIn: 'root' })
export class LangGraphThreadsAdapter {
    private readonly config = inject(LANGGRAPH_THREADS_CONFIG);
    private readonly clientState = (() => {
        const clientOptions = inject(LANGGRAPH_CLIENT_OPTIONS, { optional: true }) ?? undefined;
        const reportOperationFailure = inject(ɵLANGGRAPH_RUNTIME_OPERATION_REPORTER, { optional: true }) ??
            undefined;
        const injectedClient = inject(LANGGRAPH_CLIENT, { optional: true });
        const ownsProtectedClient = injectedClient === null &&
            (clientOptions?.defaultHeaders !== undefined ||
                reportOperationFailure !== undefined);
        return {
            client: injectedClient ??
                (ownsProtectedClient
                    ? ɵcreateProtectedLangGraphClient(this.config.apiUrl, clientOptions, createLangGraphRuntimeFetch(reportOperationFailure))
                    : createLangGraphClient(this.config.apiUrl, clientOptions)),
            protectErrors: clientOptions?.defaultHeaders !== undefined || ownsProtectedClient,
            reportOperationFailure: ownsProtectedClient
                ? reportOperationFailure
                : undefined,
        };
    })();
    private readonly client: Client = this.clientState.client;
    private readonly fallback: string = this.config.titleFallback ?? 'Untitled';
    private readonly _threads: WritableSignal<Thread[]> = signal<Thread[]>([]);
    private readonly _archived: WritableSignal<Thread[]> = signal<Thread[]>([]);
    readonly threads: Signal<Thread[]> = this._threads.asReadonly();
    readonly archivedThreads: Signal<Thread[]> = this._archived.asReadonly();
    async refresh(): Promise<void> {
        console.debug('[LangGraphThreadsAdapter.refresh] invoked');
        try {
            const list = await this.client.threads.search({ limit: 50 });
            console.debug('[LangGraphThreadsAdapter.refresh] resolved', list.length);
            const mapped = list.map((t) => this.toThread(t));
            this._threads.set(mapped
                .filter((t) => t.status !== 'archived')
                .sort((a, b) => {
                const aP = a.pinned === true;
                const bP = b.pinned === true;
                if (aP !== bP)
                    return Number(bP) - Number(aP);
                if (aP && bP) {
                    const aO = typeof a['pinnedOrder'] === 'number' ? (a['pinnedOrder'] as number) : Infinity;
                    const bO = typeof b['pinnedOrder'] === 'number' ? (b['pinnedOrder'] as number) : Infinity;
                    return aO - bO;
                }
                return 0;
            }));
            this._archived.set(mapped.filter((t) => t.status === 'archived'));
        }
        catch (e) {
            console.error('[LangGraphThreadsAdapter.refresh] failed:', this.safeError(e));
        }
    }
    async getThread(threadId: string): Promise<Thread | null> {
        try {
            const t = await this.client.threads.get(threadId);
            return this.toThread(t);
        }
        catch (e) {
            const status = safeThreadErrorStatus(e);
            if (status === 404 || status === 422)
                return null;
            throw this.safeError(e);
        }
    }
    async create(metadata: Record<string, unknown> = {}): Promise<string | null> {
        try {
            const t = await this.client.threads.create({ metadata });
            await this.refresh();
            return t.thread_id;
        }
        catch (e) {
            console.error('[LangGraphThreadsAdapter.create] failed:', this.safeError(e));
            return null;
        }
    }
    async delete(threadId: string): Promise<void> {
        await this.request(() => this.client.threads.delete(threadId));
        await this.refresh();
    }
    async rename(threadId: string, newTitle: string): Promise<void> {
        await this.request(() => this.client.threads.update(threadId, { metadata: { title: newTitle } }));
        await this.refresh();
    }
    async archive(threadId: string): Promise<void> {
        await this.request(() => this.client.threads.update(threadId, { metadata: { archived: true } }));
        await this.refresh();
    }
    async unarchive(threadId: string): Promise<void> {
        await this.request(() => this.client.threads.update(threadId, { metadata: { archived: false } }));
        await this.refresh();
    }
    async pin(threadId: string): Promise<void> {
        await this.request(() => this.client.threads.update(threadId, { metadata: { pinned: true } }));
        await this.refresh();
    }
    async unpin(threadId: string): Promise<void> {
        await this.request(() => this.client.threads.update(threadId, { metadata: { pinned: false } }));
        await this.refresh();
    }
    async moveToProject(threadId: string, projectId: string | null): Promise<void> {
        await this.request(() => this.client.threads.update(threadId, { metadata: { projectId } }));
        await this.refresh();
    }
    async reorderPinned(threadId: string, beforeId: string | null): Promise<void> {
        const current = this._threads().filter((t) => t.pinned === true);
        const moved = current.find((t) => t.id === threadId);
        if (!moved)
            return;
        const rest = current.filter((t) => t.id !== threadId);
        const next: Thread[] = [];
        for (const t of rest) {
            if (t.id === beforeId)
                next.push(moved);
            next.push(t);
        }
        if (beforeId === null)
            next.push(moved);
        await this.request(() => Promise.all(next.map((t, idx) => this.client.threads.update(t.id, { metadata: { pinnedOrder: idx } }))));
        await this.refresh();
    }
    private async request<T>(operation: () => Promise<T>): Promise<T> {
        try {
            return await operation();
        }
        catch (error) {
            throw this.safeError(error);
        }
    }
    private safeError(error: unknown): unknown {
        if (!this.clientState.protectErrors)
            return error;
        if (this.clientState.reportOperationFailure !== undefined) {
            return sanitizeLangGraphClientOperationFailure(error, this.clientState.reportOperationFailure);
        }
        return createSafeRequestError();
    }
    private toThread(t: SdkThread): Thread {
        const meta = (t.metadata ?? {}) as Record<string, unknown>;
        const rawTitle = meta['title'];
        const archived = meta['archived'] === true;
        const pinned = meta['pinned'] === true;
        const projectId = typeof meta['projectId'] === 'string' && (meta['projectId'] as string).length > 0
            ? (meta['projectId'] as string)
            : null;
        const pinnedOrder = typeof meta['pinnedOrder'] === 'number' ? (meta['pinnedOrder'] as number) : undefined;
        return {
            id: t.thread_id,
            title: typeof rawTitle === 'string' && rawTitle.length > 0 ? rawTitle : this.fallback,
            status: archived ? 'archived' : 'active',
            pinned,
            projectId,
            pinnedOrder,
            updatedAt: t.updated_at ? Date.parse(t.updated_at) : undefined,
        };
    }
}

export interface LangGraphThreadsConfig {
    apiUrl: string;
    titleFallback?: string;
}

export class MockAgentTransport implements AgentTransport {
    history: ThreadState[] = [];
    readonly historyCalls: string[] = [];
    readonly streams: Array<{
        threadId: string | null;
        payload: unknown;
        options?: LangGraphSubmitOptions;
    }> = [];
    readonly createdQueuedRuns: AgentQueueEntry[] = [];
    readonly cancelledRuns: Array<{
        threadId: string;
        runId: string;
    }> = [];
    readonly joinedRuns: Array<{
        threadId: string;
        runId: string;
    }> = [];
    private script: StreamEvent[][];
    private scriptIndex = 0;
    private streaming = false;
    private eventQueue: StreamEvent[] = [];
    private resolvers: Array<() => void> = [];
    private consumers: Array<() => void> = [];
    private closed = false;
    private pendingError: Error | null = null;
    private idle = false;
    private finished = true;
    constructor(script: StreamEvent[][] = []) {
        this.script = script;
    }
    nextBatch(): StreamEvent[] {
        if (this.scriptIndex >= this.script.length)
            return [];
        return this.script[this.scriptIndex++];
    }
    emit(events: StreamEvent[]): Promise<void> {
        this.eventQueue.push(...events);
        this.wake();
        return this.consumed();
    }
    emitError(err: Error): Promise<void> {
        this.pendingError = err;
        this.wake();
        return this.consumed();
    }
    close(): Promise<void> {
        this.closed = true;
        this.wake();
        return this.consumed();
    }
    flush(): Promise<void> {
        return this.consumed();
    }
    isStreaming(): boolean {
        return this.streaming;
    }
    async *stream(_assistantId: string, _threadId: string | null, _payload: unknown, signal: AbortSignal, options?: LangGraphSubmitOptions): AsyncIterable<StreamEvent> {
        this.streams.push({ threadId: _threadId, payload: _payload, options });
        this.streaming = true;
        this.finished = false;
        try {
            while (!this.closed && !signal.aborted) {
                if (this.pendingError)
                    throw this.pendingError;
                if (this.eventQueue.length > 0) {
                    const event = this.eventQueue.shift();
                    if (event)
                        yield event;
                }
                else {
                    this.settleConsumers();
                    this.idle = true;
                    await new Promise<void>((resolve) => {
                        if (signal.aborted) {
                            resolve();
                            return;
                        }
                        this.resolvers.push(resolve);
                    });
                    this.idle = false;
                }
            }
            if (signal.aborted)
                return;
            while (this.eventQueue.length > 0) {
                const event = this.eventQueue.shift();
                if (event)
                    yield event;
            }
        }
        finally {
            this.streaming = false;
            this.idle = false;
            this.finished = true;
            this.settleConsumers();
        }
    }
    async createQueuedRun(_assistantId: string, threadId: string, payload: unknown, signal: AbortSignal, options?: LangGraphSubmitOptions): Promise<AgentQueueEntry> {
        void signal;
        const entry: AgentQueueEntry = {
            id: `queued-run-${this.createdQueuedRuns.length + 1}`,
            threadId,
            values: payload,
            options: { ...options, multitaskStrategy: 'enqueue' },
            createdAt: new Date(),
        };
        this.createdQueuedRuns.push(entry);
        return entry;
    }
    async cancelRun(threadId: string, runId: string, signal: AbortSignal): Promise<void> {
        void signal;
        this.cancelledRuns.push({ threadId, runId });
    }
    async getHistory(threadId: string, signal: AbortSignal): Promise<ThreadState[]> {
        void signal;
        this.historyCalls.push(threadId);
        return this.history;
    }
    async *joinStream(threadId: string, runId: string, lastEventId: string | undefined, signal: AbortSignal): AsyncIterable<StreamEvent> {
        void lastEventId;
        void signal;
        this.joinedRuns.push({ threadId, runId });
        yield { type: 'values', values: { queued: true } };
    }
    private wake(): void {
        const resolve = this.resolvers.shift();
        if (resolve)
            resolve();
    }
    private consumed(): Promise<void> {
        const alreadySettled = this.finished ||
            (this.idle && this.eventQueue.length === 0 && this.pendingError === null && !this.closed);
        if (alreadySettled)
            return new Promise<void>((resolve) => setTimeout(resolve, 0));
        return new Promise<void>((resolve) => { this.consumers.push(resolve); });
    }
    private settleConsumers(): void {
        const pending = this.consumers;
        this.consumers = [];
        for (const resolve of pending)
            setTimeout(resolve, 0);
    }
}

