export function createInMemoryClientToolExecutionStore(): ClientToolExecutionStore {
    const records = new Map<string, ClientToolExecutionRecord>();
    return {
        async claim(key: ClientToolExecutionKey): Promise<'claimed' | ClientToolExecutionRecord> {
            const existing = records.get(mapKey(key));
            if (existing)
                return cloneRecord(existing);
            records.set(mapKey(key), { status: 'executing' });
            return 'claimed';
        },
        async record(key: ClientToolExecutionKey, result: ClientToolResult): Promise<void> {
            records.set(mapKey(key), { status: 'done', result: cloneResult(result) });
        },
        async lookup(threadId: string, toolCallIds: readonly string[]): Promise<Record<string, ClientToolExecutionRecord>> {
            const out: Record<string, ClientToolExecutionRecord> = {};
            for (const toolCallId of toolCallIds) {
                const existing = records.get(mapKey({ threadId, toolCallId }));
                if (existing)
                    out[toolCallId] = cloneRecord(existing);
            }
            return out;
        },
    };
}

export function createPostgresClientToolExecutionStore(sql: PostgresTaggedSql, opts: PostgresClientToolExecutionStoreOptions = {}): ClientToolExecutionStore {
    const tenantId = opts.tenantId ?? '';
    return {
        async claim(key: ClientToolExecutionKey): Promise<'claimed' | ClientToolExecutionRecord> {
            const inserted = await sql `
        INSERT INTO threadplane_client_tool_executions
          (tenant_id, thread_id, tool_call_id, status)
        VALUES (${tenantId}, ${key.threadId}, ${key.toolCallId}, 'executing')
        ON CONFLICT (tenant_id, thread_id, tool_call_id) DO NOTHING
        RETURNING status, result
      `;
            if (inserted.length > 0)
                return 'claimed';
            const existing = await sql `
        SELECT status, result
        FROM threadplane_client_tool_executions
        WHERE tenant_id = ${tenantId}
          AND thread_id = ${key.threadId}
          AND tool_call_id = ${key.toolCallId}
        LIMIT 1
      `;
            return rowToRecord(existing[0]);
        },
        async record(key: ClientToolExecutionKey, result: ClientToolResult): Promise<void> {
            await sql `
        INSERT INTO threadplane_client_tool_executions
          (tenant_id, thread_id, tool_call_id, status, result)
        VALUES (${tenantId}, ${key.threadId}, ${key.toolCallId}, 'done', ${JSON.stringify(result)}::jsonb)
        ON CONFLICT (tenant_id, thread_id, tool_call_id) DO UPDATE
        SET status = 'done',
            result = CASE
              WHEN threadplane_client_tool_executions.status = 'done'
                THEN threadplane_client_tool_executions.result
              ELSE EXCLUDED.result
            END,
            updated_at = now()
      `;
        },
        async lookup(threadId: string, toolCallIds: readonly string[]): Promise<Record<string, ClientToolExecutionRecord>> {
            if (toolCallIds.length === 0)
                return {};
            const rows = await sql `
        SELECT tool_call_id, status, result
        FROM threadplane_client_tool_executions
        WHERE tenant_id = ${tenantId}
          AND thread_id = ${threadId}
          AND tool_call_id = ANY(${[...toolCallIds]})
      `;
            const out: Record<string, ClientToolExecutionRecord> = {};
            for (const row of rows) {
                if (typeof row['tool_call_id'] !== 'string')
                    continue;
                out[row['tool_call_id']] = rowToRecord(row);
            }
            return out;
        },
    };
}

export function extractClientToolResultMessages(messages: readonly BaseMessage[]): ClientToolResultMessage[] {
    const out: ClientToolResultMessage[] = [];
    for (const message of messages) {
        const toolCallId = toolCallIdFromMessage(message);
        if (!toolCallId)
            continue;
        out.push({ toolCallId, result: resultFromMessageContent(message.content) });
    }
    return out;
}

export function filterDuplicateClientToolResultMessages(input: {
    readonly messages: readonly BaseMessage[];
    readonly duplicateToolCallIds: ReadonlySet<string>;
}): BaseMessage[] {
    return input.messages.filter((message) => {
        const toolCallId = toolCallIdFromMessage(message);
        return !toolCallId || !input.duplicateToolCallIds.has(toolCallId);
    });
}

export function hasClientToolCall(state: ClientToolsState): boolean {
    const names = clientToolNames(state);
    return toolCalls(lastMessage(state)).some((c) => {
        const n = callName(c);
        return n !== undefined && names.has(n);
    });
}

export function hasServerToolCall(state: ClientToolsState, serverToolNames: Iterable<string>): boolean {
    const server = new Set(serverToolNames);
    const client = clientToolNames(state);
    return toolCalls(lastMessage(state)).some((c) => {
        const n = callName(c);
        return n !== undefined && (server.has(n) || !client.has(n));
    });
}

export function lastMessage(state: ClientToolsState): BaseMessage | undefined {
    const msgs = state.messages ?? [];
    return msgs.length ? msgs[msgs.length - 1] : undefined;
}

export function lookupClientToolExecutions(input: {
    readonly threadId: string;
    readonly toolCallIds: readonly string[];
    readonly store: ClientToolExecutionStore;
}): Promise<Record<string, ClientToolExecutionRecord>> {
    return input.store.lookup(input.threadId, input.toolCallIds);
}

export async function recordClientToolResults(input: RecordClientToolResultsInput): Promise<RecordClientToolResultsResult> {
    const recordedToolCallIds: string[] = [];
    const duplicateToolCallIds: string[] = [];
    for (const entry of extractClientToolResultMessages(input.messages)) {
        const key = { threadId: input.threadId, toolCallId: entry.toolCallId };
        const claim = await input.store.claim(key);
        if (claim === 'claimed') {
            await input.store.record(key, entry.result);
            recordedToolCallIds.push(entry.toolCallId);
            continue;
        }
        if (claim.status === 'done') {
            duplicateToolCallIds.push(entry.toolCallId);
            continue;
        }
        await input.store.record(key, entry.result);
        recordedToolCallIds.push(entry.toolCallId);
    }
    return { recordedToolCallIds, duplicateToolCallIds };
}

export function routeAfterAgent(state: ClientToolsState, serverToolNames: Iterable<string>, opts?: {
    toolsNode?: string;
    end?: string;
}): string {
    const toolsNode = opts?.toolsNode ?? 'server_tools';
    const end = opts?.end ?? '__end__';
    return hasServerToolCall(state, serverToolNames) ? toolsNode : end;
}

