    lastChange?: () => StateChangeRecord | undefined;
}

export interface StandardSchemaV1<Input = unknown, Output = Input> {
    readonly '~standard': StandardSchemaProps<Input, Output>;
}

export interface StateChangeRecord {
    readonly path: string;
    readonly value: unknown;
}

export function defineAngularRegistry(componentMap: RegistryInput): AngularRegistry {
    const map = new Map<string, NormalizedEntry>();
    for (const [name, entry] of Object.entries(componentMap)) {
        map.set(name, normalize(entry));
    }
    return {
        getEntry: (name: string) => map.get(name),
        names: () => [...map.keys()],
    };
}

export function injectRenderHost(): RenderHost {
    return inject(RENDER_HOST);
}

export function overrideViews(base: ViewRegistry, overrides: Record<string, Type<unknown> | RenderViewEntry>): ViewRegistry {
    return Object.freeze({ ...base, ...overrides });
}

export function provideRender(config: RenderConfig) {
    return makeEnvironmentProviders([
        { provide: RENDER_CONFIG, useValue: config },
        RenderLifecycleService,
        { provide: RENDER_LIFECYCLE, useExisting: RenderLifecycleService },
    ]);
}

export function provideViews(registry: ViewRegistry) {
    return makeEnvironmentProviders([
        { provide: VIEW_REGISTRY, useValue: registry },
    ]);
}

export function signalStateStore(initialState: StateModel = {}): SignalStateStore {
    const state = signal<StateModel>(initialState);
    const listeners = new Set<() => void>();
    let lastChange: StateChangeRecord | undefined;
    function notify(): void {
        for (const listener of listeners)
            listener();
    }
    return {
        get(path: string): unknown {
            return getByPath(state(), parsePointer(path));
        },
        set(path: string, value: unknown): void {
            const segments = parsePointer(path);
            const current = getByPath(state(), segments);
            if (current === value)
                return;
            state.set(setByPath(state(), segments, value) as StateModel);
            lastChange = { path, value };
            notify();
        },
        update(updates: Record<string, unknown>): void {
            let current = state();
            let applied: StateChangeRecord | undefined;
            for (const [path, value] of Object.entries(updates)) {
                const segments = parsePointer(path);
                const existing = getByPath(current, segments);
                if (existing !== value) {
                    current = setByPath(current, segments, value) as StateModel;
                    applied = { path, value };
                }
            }
            if (applied) {
                state.set(current);
                lastChange = applied;
                notify();
            }
        },
        getSnapshot(): StateModel {
            return state();
        },
        subscribe(listener: () => void): () => void {
            listeners.add(listener);
            return () => {
                listeners.delete(listener);
            };
        },
        lastChange(): StateChangeRecord | undefined {
            return lastChange;
        },
    };
}

export function toRenderRegistry(registry: ViewRegistry): AngularRegistry {
    return defineAngularRegistry(registry);
}

export function views(map: Record<string, Type<unknown> | RenderViewEntry>): ViewRegistry {
    return Object.freeze({ ...map });
}

export function withViews(base: ViewRegistry, additions: Record<string, Type<unknown> | RenderViewEntry>): ViewRegistry {
    return Object.freeze({ ...additions, ...base });
}

export function withoutViews(base: ViewRegistry, ...names: string[]): ViewRegistry {
    const result = { ...base };
    for (const name of names)
        delete result[name];
    return Object.freeze(result);
}

