    token?: string;
    captureLocal?: boolean;
    host?: string;
};

export interface DevelopmentRuntime {
    touch(): void;
    milestone(kind: DevelopmentMilestone, durationMs?: number): void;
    dispose(): void;
}

export interface DevelopmentRuntimeOptions {
    integration: DevelopmentIntegration;
    packageName: '@threadplane/langgraph' | '@threadplane/ag-ui' | '@threadplane/render';
    packageVersion: string;
    installationToken?: string | null;
    enabled?: () => boolean;
}

export interface ThreadplaneBrowserRuntimeTelemetry {
    transport: string;
    surface?: string;
    provider?: string;
    model?: string;
}

export interface ThreadplaneBrowserStreamErrorTelemetry extends ThreadplaneBrowserStreamTelemetry {
    error?: unknown;
